  {
   "@type": "Question",
   "name": "Is it okay to turn the heat off when I go out?",
   "acceptedAnswer": {
    "@type": "Answer",
    "text": "For a healthy adult dog alone for a few hours in a well-insulated home, it can be fine. But in midwinter, or for a puppy, senior, small or short-coated dog, it's better to leave it on away mode or a low temperature."
   }
  },
  {
   "@type": "Question",
   "name": "What indoor temperature is right for a dog?",
   "acceptedAnswer": {
    "@type": "Answer",
    "text": "Dogs are commonly said to feel comfortable at about 18–22°C (64–72°F). Dogs who feel the cold can use it a bit warmer, while dogs with a thick double coat, like a Jindo, are fine a little cooler."
   }
  },
  {
   "@type": "Question",
   "name": "Is it bad to turn the heat up too high?",
   "acceptedAnswer": {
    "@type": "Answer",
    "text": "Yes. Underfloor heating makes the floor hot, so lying on it for a long time can cause low-temperature burns, and the air gets dry. Make sure your dog can move to a cooler spot."
   }
  },
  {
   "@type": "Question",
   "name": "Can I leave a heating pad or space heater on when I go out?",
   "acceptedAnswer": {
    "@type": "Answer",
    "text": "Not while your dog is alone. They could chew the cord or get burned lying too close, and there's a fire risk."
   }
  }
 ]
